import { apiRequest } from './client.js';

// HTTP for OSINT Trail (docs/API_SPEC.md "OSINT Trail"). Every page of evidence is generated by the server for the
// caller's team; the browser only ever asks for bounded pages.
const base = (track) => `/osint/cases/${encodeURIComponent(track)}`;
const query = (params) => {
  const q = new URLSearchParams(Object.entries(params).filter(([, v]) => v !== undefined && v !== '').map(([k, v]) => [k, String(v)]));
  return q.size > 0 ? `?${q}` : '';
};

export const listCases = () => apiRequest('/osint/cases');
export const getCase = (track) => apiRequest(base(track));
export const getSource = (track, source, params = {}, { signal } = {}) => apiRequest(`${base(track)}/sources/${encodeURIComponent(source)}${query(params)}`, { signal });
export const searchCase = (track, q, params = {}, { signal } = {}) => apiRequest(`${base(track)}/search${query({ q, ...params })}`, { signal });
export const submitAnswer = (track, n, answer) => apiRequest(`${base(track)}/questions/${n}/answer`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ answer }),
});
export const openHint = (track, n) => apiRequest(`${base(track)}/questions/${n}/hints`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: '{}',
});

// The team's shared case board (docs/OSINT_TRAIL.md "Case board"). Saves carry the version the edit started from.
export const getBoard = (track) => apiRequest(`${base(track)}/board`);
// `keepalive` lets the last save finish while the page is being left.
export const saveBoard = (track, payload, { keepalive = false } = {}) => apiRequest(`${base(track)}/board`, {
  method: 'PUT',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify(payload),
  ...(keepalive ? { keepalive: true } : {}),
});
// Exact N of M for the SAVED board; strictly rate limited by the server (3 a minute, 10 an hour).
export const checkBoard = (track) => apiRequest(`${base(track)}/board/check`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: '{}',
});
export const listEvidence = (track, params = {}, { signal } = {}) => apiRequest(`${base(track)}/board/evidence${query(params)}`, { signal });
